<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTemplateVO;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;

trait TemplateAssetTemplateAttributeHolder
{
    protected TemplateAssetTemplateVO|TemplateRef|null $template = null;
    protected bool $templateAssigned = false;

    public function getTemplateOrCurrent(TemplateAssetTemplateVO $template): TemplateAssetTemplateVO
    {
        if ($this->templateAssigned) {
            \assert(null !== $this->template);
            return TemplateAssetTemplateVO::from($this->template);
        } else {
            return $template;
        }
    }
    public function templateTryBuildInitial(ConstraintFailList $error): ?TemplateAssetTemplateVO
    {
        return  TemplateAssetTemplateVO::tryFrom($this->templateAssigned ? $this->template : null, $error);
    }
    public function template(TemplateAssetTemplateVO|TemplateRef $template): static
    {
        $this->template = $template;
        $this->templateAssigned = true;
        return $this;
    }
    public function getTemplate(): ?TemplateRef
    {
        return $this->template instanceof TemplateAssetTemplateVO ? $this->template->value() : $this->template;
    }
    public function isTemplateAssigned(): bool
    {
        return $this->templateAssigned;
    }
    public function writeTemplateTo(mixed $att): void
    {
        if ($this->templateAssigned) {
            \assert(null !== $this->template);
            $att->template($this->template);
        }
    }
    public function readTemplateFrom(mixed $att): void
    {
        if ($att->isTemplateAssigned()) {
            $template = $att->getTemplate();
            \assert(null !== $template);
            $this->template($template);
        }
    }
    public function unsetTemplate(): static
    {
        $this->templateAssigned = false;
        return $this;
    }
    protected function withDefaultTemplate(): void
    {
    }
    protected function withAssertedTemplateRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->templateAssigned = $this->templateAssigned) {
            $value->template = TemplateAssetTemplateVO::tryFrom($this->template, $errorsList);
        }
    }
}
